import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import NotificationBell from './NotificationBell';
import { 
  Home, 
  User, 
  Briefcase, 
  Trophy, 
  Users, 
  LogOut, 
  Menu, 
  X,
  GraduationCap,
  MessageCircle,
  Star,
  Award,
  BarChart3,
  Sparkles,
  Zap,
  ChevronDown,
  Grid3X3,
  Shield
} from 'lucide-react';

const Navbar = () => {
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const mainNavigation = [
    { name: 'Dashboard', href: '/dashboard', icon: Home },
    { name: 'Jobs', href: '/jobs', icon: Briefcase },
    { name: 'Competitions', href: '/competitions', icon: Trophy },
    ...(user?.role === 'student' ? [
      { name: 'Recommendations', href: '/recommendations', icon: Star },
      { name: 'Leaderboard', href: '/leaderboard', icon: Award }
    ] : []),
    { name: 'Profile', href: '/profile', icon: User },
  ];

  const panelNavigation = [
    ...(user?.role !== 'student' ? [{ name: 'Students', href: '/students', icon: Users }] : []),
    { name: 'Chat', href: '/chat', icon: MessageCircle },
    ...(user?.role !== 'student' ? [{ name: 'Analytics', href: '/analytics', icon: BarChart3 }] : []),
    ...(user?.role === 'admin' ? [{ name: 'Admin Panel', href: '/admin', icon: Shield }] : []),
  ];

  const allNavigation = [...mainNavigation, ...panelNavigation];

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="bg-academic-ivory/95 backdrop-blur-md shadow-2xl border-b border-academic-navy/10 sticky top-0 z-50">
      <div className="absolute inset-0 bg-gradient-to-r from-academic-navy/5 via-academic-burgundy/5 to-academic-charcoal/5"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <div className="flex justify-between h-18">
          {/* Logo and Brand */}
          <div className="flex items-center">
            <Link to="/dashboard" className="flex items-center space-x-3 group">
              <div className="relative">
                <div className="bg-gradient-to-r from-academic-navy to-academic-burgundy p-3 rounded-xl shadow-lg group-hover:shadow-xl transition-all duration-300 group-hover:scale-110">
                  <GraduationCap className="h-7 w-7 text-academic-ivory" />
                </div>
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-gradient-to-r from-accent-600 to-accent-700 rounded-full animate-pulse">
                  <Sparkles className="h-3 w-3 text-academic-ivory p-0.5" />
                </div>
              </div>
              <div className="hidden sm:block">
                <h1 className="text-lg font-semibold bg-gradient-to-r from-academic-navy to-academic-burgundy bg-clip-text text-transparent group-hover:from-academic-burgundy group-hover:to-academic-navy transition-all duration-300">
                  College Talent Hub
                </h1>
              </div>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-2">
            {mainNavigation.map((item) => {
              const Icon = item.icon;
              return (
                <Link
                  key={item.name}
                  to={item.href}
                  className={`relative flex items-center space-x-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all duration-300 transform hover:scale-105 group ${
                    isActive(item.href)
                      ? 'bg-gradient-to-r from-academic-navy to-academic-burgundy text-academic-ivory shadow-lg'
                      : 'text-academic-charcoal hover:text-academic-ivory hover:bg-gradient-to-r hover:from-academic-navy hover:to-academic-burgundy hover:shadow-lg'
                  }`}
                >
                  <Icon className={`h-5 w-5 transition-transform duration-300 ${
                    isActive(item.href) ? 'animate-pulse' : 'group-hover:rotate-12'
                  }`} />
                  <span>{item.name}</span>
                  {isActive(item.href) && (
                    <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-yellow-400 rounded-full animate-bounce"></div>
                  )}
                </Link>
              );
            })}

            {/* Dropdown Panel */}
            {panelNavigation.length > 0 && (
              <div className="relative">
                <button
                  onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                  className={`relative flex items-center space-x-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all duration-300 transform hover:scale-105 group ${
                    panelNavigation.some(item => isActive(item.href))
                      ? 'bg-gradient-to-r from-academic-navy to-academic-burgundy text-academic-ivory shadow-lg'
                      : 'text-academic-charcoal hover:text-academic-ivory hover:bg-gradient-to-r hover:from-academic-navy hover:to-academic-burgundy hover:shadow-lg'
                  }`}
                >
                  <Grid3X3 className={`h-5 w-5 transition-transform duration-300 ${
                    panelNavigation.some(item => isActive(item.href)) ? 'animate-pulse' : 'group-hover:rotate-12'
                  }`} />
                  <span>More</span>
                  <ChevronDown className={`h-4 w-4 transition-transform duration-300 ${
                    isDropdownOpen ? 'rotate-180' : ''
                  }`} />
                  {panelNavigation.some(item => isActive(item.href)) && (
                    <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-yellow-400 rounded-full animate-bounce"></div>
                  )}
                </button>

                {/* Dropdown Menu */}
                {isDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 bg-academic-ivory rounded-2xl shadow-2xl border border-academic-navy/10 backdrop-blur-sm bg-opacity-95 z-50 animate-fade-in">
                    <div className="p-2">
                      {panelNavigation.map((item) => {
                        const Icon = item.icon;
                        return (
                          <Link
                            key={item.name}
                            to={item.href}
                            onClick={() => setIsDropdownOpen(false)}
                            className={`flex items-center space-x-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all duration-300 transform hover:scale-105 group ${
                              isActive(item.href)
                                ? 'bg-gradient-to-r from-academic-navy to-academic-burgundy text-academic-ivory shadow-lg'
                                : 'text-academic-charcoal hover:text-academic-ivory hover:bg-gradient-to-r hover:from-academic-navy hover:to-academic-burgundy hover:shadow-lg'
                            }`}
                          >
                            <Icon className={`h-5 w-5 transition-transform duration-300 ${
                              isActive(item.href) ? 'animate-pulse' : 'group-hover:rotate-12'
                            }`} />
                            <span>{item.name}</span>
                          </Link>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* User Menu */}
          <div className="flex items-center space-x-4">
            {/* Notification Bell for Students */}
            <div className="transform hover:scale-110 transition-transform duration-300">
              <NotificationBell />
            </div>

            <div className="hidden md:block text-right bg-gradient-to-r from-neutral-50 to-neutral-100 px-4 py-2 rounded-xl border border-academic-navy/10">
              <p className="text-sm font-bold text-academic-charcoal flex items-center space-x-1">
                <span>{user?.name}</span>
                <Zap className="h-4 w-4 text-accent-600" />
              </p>
              <p className="text-xs font-medium text-academic-navy capitalize">{user?.role}</p>
            </div>
            <button
              onClick={handleLogout}
              className="flex items-center space-x-2 px-4 py-2.5 rounded-xl text-sm font-semibold text-academic-charcoal hover:text-academic-ivory hover:bg-gradient-to-r hover:from-accent-700 hover:to-accent-800 transition-all duration-300 transform hover:scale-105 hover:shadow-lg group"
            >
              <LogOut className="h-5 w-5 group-hover:rotate-12 transition-transform duration-300" />
              <span className="hidden sm:block">Logout</span>
            </button>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="inline-flex items-center justify-center p-3 rounded-xl bg-gradient-to-r from-academic-navy to-academic-burgundy text-academic-ivory hover:from-academic-burgundy hover:to-academic-navy transition-all duration-300 transform hover:scale-110 shadow-lg"
              >
                {isMobileMenuOpen ? (
                  <X className="h-6 w-6 rotate-90 transition-transform duration-300" />
                ) : (
                  <Menu className="h-6 w-6 transition-transform duration-300" />
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden animate-fade-in">
          <div className="px-4 pt-4 pb-6 space-y-3 bg-gradient-to-br from-neutral-50 via-neutral-100 to-neutral-200 backdrop-blur-md border-t border-academic-navy/20">
            <div className="bg-academic-ivory/80 backdrop-blur-sm px-4 py-3 rounded-xl border border-academic-navy/20 mb-4">
              <p className="text-lg font-bold text-academic-charcoal flex items-center space-x-2">
                <span>{user?.name}</span>
                <Sparkles className="h-5 w-5 text-accent-600" />
              </p>
              <p className="text-sm font-medium text-academic-navy capitalize">{user?.role}</p>
            </div>
            {allNavigation.map((item) => {
              const Icon = item.icon;
              return (
                <Link
                  key={item.name}
                  to={item.href}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center space-x-3 px-4 py-3 rounded-xl text-base font-semibold transition-all duration-300 transform hover:scale-105 ${
                    isActive(item.href)
                      ? 'bg-gradient-to-r from-academic-navy to-academic-burgundy text-academic-ivory shadow-lg'
                      : 'text-academic-charcoal hover:text-academic-ivory hover:bg-gradient-to-r hover:from-academic-navy hover:to-academic-burgundy bg-academic-ivory/60 hover:shadow-lg'
                  }`}
                >
                  <Icon className={`h-6 w-6 ${
                    isActive(item.href) ? 'animate-pulse' : ''
                  }`} />
                  <span>{item.name}</span>
                </Link>
              );
            })}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
